p-6 overflow-y-auto flex-1 bg-darkbg"><input type="hidden" id="pmgNodeId"><input type="hidden" id="pmgHostName"><input type="hidden" id="pmgInternalName"><div id="pmg-tab-spam" class="h-full flex flex-col"><div class="flex justify-between items-center mb-4"><h3 class="text-white font-bold">Zurückgehaltene Mails</h3><button onclick="loadPmgSpamQueue(document.getElementById('pmgNodeId').value)" class="text-xs bg-darkcard border border-darkborder hover:border-pmg text-white px-3 py-1.5 rounded transition-colors">🔄 Aktualisieren</button></div><div class="overflow-y-auto flex-1 bg-darkcard border border-darkborder rounded-lg relative"><table class="w-full text-left text-sm text-gray-400"><thead class="bg-darkbg border-b border-darkborder text-xs uppercase sticky top-0 z-10"><tr><th class="px-4 py-3">Datum</th><th class="px-4 py-3">Absender</th><th class="px-4 py-3">Empfänger</th><th class="px-4 py-3">Betreff</th><th class="px-4 py-3 text-center">Score</th><th class="px-4 py-3 text-right">Aktion</th></tr></thead><tbody id="pmgSpamTable" class="divide-y divide-darkborder"></tbody></table></div></div><div id="pmg-tab-tracking" class="hidden h-full flex flex-col"><div class="flex gap-4 mb-4 items-end"><div class="flex-1"><label class="block text-xs font-medium text-gray-500 mb-1">Nach E-Mail Adresse filtern (Letzte 24h)</label><input type="text" id="pmgTrackingFilter" placeholder="z.B. spammer@evil.com oder user@firma.de" class="w-full bg-darkcard border border-darkborder rounded p-2 text-white text-sm" onkeydown="if(event.key === 'Enter') loadPmgTracking()"></div><button onclick="loadPmgTracking()" class="bg-pmg hover:bg-blue-600 text-white font-bold py-2 px-6 rounded text-sm transition-colors">Suchen</button></div><div class="overflow-y-auto flex-1 bg-darkcard border border-darkborder rounded-lg relative"><table class="w-full text-left text-sm text-gray-400"><thead class="bg-darkbg border-b border-darkborder text-xs uppercase sticky top-0 z-10"><tr><th class="px-4 py-3">Zeit</th><th class="px-4 py-3">Absender</th><th class="px-4 py-3">Empfänger</th><th class="px-4 py-3">Status</th></tr></thead><tbody id="pmgTrackingTable" class="divide-y divide-darkborder"></tbody></table></div></div><div id="pmg-tab-queues" class="hidden h-full flex flex-col"><div class="flex justify-between items-center mb-4"><h3 class="text-white font-bold">Aktuelle Postfix Warteschlangen</h3><button onclick="loadPmgQueues()" class="text-xs bg-darkcard border border-darkborder hover:border-pmg text-white px-3 py-1.5 rounded transition-colors">🔄 Aktualisieren</button></div><div class="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6" id="pmgQueuesSummary"><div class="bg-darkcard border border-darkborder rounded-xl p-5 text-center animate-pulse"><p class="text-gray-500">Lade...</p></div></div><div class="overflow-y-auto flex-1 bg-darkcard border border-darkborder rounded-lg relative"><table class="w-full text-left text-sm text-gray-400"><thead class="bg-darkbg border-b border-darkborder text-xs uppercase sticky top-0 z-10"><tr><th class="px-4 py-3">Queue</th><th class="px-4 py-3">Zeit</th><th class="px-4 py-3">Absender</th><th class="px-4 py-3">Empfänger</th><th class="px-4 py-3">Grund</th></tr></thead><tbody id="pmgQueueTable" class="divide-y divide-darkborder"></tbody></table></div></div><div id="pmg-tab-settings" class="hidden h-full flex flex-col overflow-y-auto"><div class="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-10"><div class="bg-darkcard border border-darkborder rounded-xl p-5 shadow-lg border-l-4 border-l-pmg h-fit"><h3 class="text-white font-bold mb-4 text-lg">⚙️ Mail Proxy Konfiguration</h3><div class="space-y-4"><div><label class="block text-xs font-bold text-gray-400 uppercase mb-1">Default Relay (Ziel für saubere Mails)</label><input type="text" id="pmgCfgRelay" class="w-full bg-darkbg border border-darkborder focus:border-pmg rounded p-2 text-white font-mono text-sm" placeholder="z.B. 192.168.1.10"></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-xs font-bold text-gray-400 uppercase mb-1">Externer Port (IN)</label><input type="number" id="pmgCfgExtPort" class="w-full bg-darkbg border border-darkborder rounded p-2 text-white font-mono text-sm"></div><div><label class="block text-xs font-bold text-gray-400 uppercase mb-1">Interner Port (OUT)</label><input type="number" id="pmgCfgIntPort" class="w-full bg-darkbg border border-darkborder rounded p-2 text-white font-mono text-sm"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-xs font-bold text-gray-400 uppercase mb-1">TLS</label><select id="pmgCfgTls" class="w-full bg-darkbg border border-darkborder rounded p-2 text-white text-sm"><option value="1">Aktiviert</option><option value="0">Deaktiviert</option></select></div><div><label class="block text-xs font-bold text-gray-400 uppercase mb-1">TLS Logging</label><select id="pmgCfgTlsLog" class="w-full bg-darkbg border border-darkborder rounded p-2 text-white text-sm"><option value="1">Aktiviert</option><option value="0">Deaktiviert</option></select></div></div><button onclick="savePmgConfig()" class="w-full bg-pmg hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-colors mt-2">Proxy Config speichern</button></div></div><div class="space-y-6"><div class="bg-darkcard border border-darkborder rounded-xl p-5 shadow-lg"><h3 class="text-white font-bold mb-4 text-lg">🌍 Relay Domains</h3><div class="flex gap-2 mb-3"><input type="text" id="pmgNewDomain" placeholder="z.B. firma.de" class="flex-1 bg-darkbg border border-darkborder rounded p-2 text-white text-sm"><button onclick="addPmgDomain()" class="bg-proxmox hover:bg-orange-600 text-white font-bold px-4 rounded text-sm">Hinzufügen</button></div><div id="pmgDomainsContainer" class="space-y-1 max-h-40 overflow-y-auto"><p class="text-gray-500 text-sm">Lade Domains...</p></div></div><div class="bg-darkcard border border-darkborder rounded-xl p-5 shadow-lg"><h3 class="text-white font-bold mb-4 text-lg">🛜 Trusted Networks (Outbound)</h3><div class="flex gap-2 mb-3"><input type="text" id="pmgNewNetwork" placeholder="z.B. 192.168.1.0/24" class="flex-1 bg-darkbg border border-darkborder rounded p-2 text-white text-sm"><button onclick="addPmgNetwork()" class="bg-proxmox hover:bg-orange-600 text-white font-bold px-4 rounded text-sm">Hinzufügen</button></div><div id="pmgNetworksContainer" class="space-y-1 max-h-40 overflow-y-auto"><p class="text-gray-500 text-sm">Lade Netzwerke...</p></div></div></div><div class="bg-darkcard border border-darkborder rounded-xl p-5 shadow-lg border-l-4 border-l-emerald-500 lg:col-span-2"><h3 class="text-white font-bold mb-4 text-lg">🔒 SSL Zertifikate</h3><div class="grid grid-cols-1 lg:grid-cols-2 gap-8"><div><h4 class="text-xs font-bold text-gray-400 uppercase mb-3 border-b border-darkborder pb-1">Installierte Zertifikate</h4><div id="pmgSslContainer" class="space-y-3"><p class="text-gray-500 text-sm">Lade Zertifikate...</p></div></div><div class="bg-darkbg p-4 rounded border border-darkborder"><h4 class="text-xs font-bold text-emerald-500 uppercase mb-3 border-b border-darkborder pb-1">Neues Zertifikat installieren</h4><div class="space-y-3"><div><label class="block text-xs font-medium text-gray-500 mb-1">Private Key (.key)</label><textarea id="pmgSslKey" rows="3" class="w-full bg-darkcard border border-darkborder rounded p-2 text-green-400 font-mono text-xs" placeholder="-----BEGIN PRIVATE KEY-----..."></textarea></div><div><label class="block text-xs font-medium text-gray-500 mb-1">Zertifikat (.pem / .crt inkl. Chain)</label><textarea id="pmgSslCert" rows="4" class="w-full bg-darkcard border border-darkborder rounded p-2 text-blue-400 font-mono text-xs" placeholder="-----BEGIN CERTIFICATE-----..."></textarea></div><button onclick="uploadPmgSsl()" class="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 rounded transition-colors text-sm">Zertifikat hochladen & Dienste neustarten</button></div></div></div></div></div></div></div></div></div>

