        <div class="p-5 border-b border-darkborder flex justify-between items-center bg-darkbg">
            <h2 class="text-xl font-bold text-white flex items-center gap-2">📦 System Updates (APT)</h2>
            <button onclick="closeUpdateManager()" class="text-gray-400 hover:text-white transition-colors text-2xl">✕</button>
        </div>
        <div class="p-6 overflow-y-auto flex-1 bg-darkbg" id="updateManagerContent">
